    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>(() => { const places = @json($mapPlaces); const map = L.map('provider-business-map').setView([-2.5489, 118.0149], 5); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; OpenStreetMap contributors' }).addTo(map); const bounds = []; const coordinateFromUrl = url => { if (!url) return null; const match = url.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/) || url.match(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/) || url.match(/[?&](?:q|query)=(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/); return match ? [Number(match[1]), Number(match[2])] : null; }; const addMarker = (place, coordinates) => { const marker = L.marker(coordinates).addTo(map).bindTooltip(place.name, { permanent: true, direction: 'top', className: 'provider-map-label' }); const popup = document.createElement('div'); const title = document.createElement('strong'); title.textContent = place.name; popup.appendChild(title); if (place.maps_url) { const link = document.createElement('a'); link.href = place.maps_url; link.target = '_blank'; link.rel = 'noopener noreferrer'; link.textContent = 'Buka Google Maps'; popup.appendChild(document.createElement('br')); popup.appendChild(link); } marker.bindPopup(popup); bounds.push(coordinates); if (bounds.length === 1) map.setView(coordinates, 14); else map.fitBounds(bounds, { padding: [30, 30] }); }; const geocode = async place => { const storedCoordinates = place.latitude !== null && place.longitude !== null ? [Number(place.latitude), Number(place.longitude)] : null; const coordinates = storedCoordinates || coordinateFromUrl(place.maps_url); if (coordinates) return addMarker(place, coordinates); if (!place.query) return; try { const response = await fetch(`{{ route('provider.map.geocode') }}?q=${encodeURIComponent(place.query)}`, { headers: { Accept: 'application/json' } }); if (!response.ok) return; const result = await response.json(); if (result.latitude !== undefined && result.longitude !== undefined) addMarker(place, [Number(result.latitude), Number(result.longitude)]); } catch (error) { /* Lokasi yang gagal di-geocode dilewati. */ } }; places.forEach((place, index) => setTimeout(() => geocode(place), index * 1100)); })();</script>
